package com.saumyasolar.service;
import com.saumyasolar.domain.SiteSurveyAttachment;import com.saumyasolar.repo.SiteSurveyAttachmentRepository;import com.saumyasolar.security.Principal;import jakarta.transaction.Transactional;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;import java.io.IOException;import java.nio.file.*;import java.time.Instant;import java.util.*;
@Service
public class SurveyAttachmentService {
 private static final long MAX_SIZE=10L*1024*1024;private final Path root;private final SiteSurveyAttachmentRepository attachments;private final SurveyLifecycleService surveys;
 public SurveyAttachmentService(@Value("${app.survey.attachment-location:./data/private-survey-attachments}") String location,SiteSurveyAttachmentRepository attachments,SurveyLifecycleService surveys,PrivateObjectStorageService storage){this.root=Path.of(location).toAbsolutePath().normalize();this.attachments=attachments;this.surveys=surveys;this.storage=storage;}
 @Transactional public SiteSurveyAttachment upload(UUID surveyId,MultipartFile file,Principal p){surveys.get(surveyId,p);if(file==null||file.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a survey evidence file");if(file.getSize()>MAX_SIZE)throw new ResponseStatusException(HttpStatus.PAYLOAD_TOO_LARGE,"Survey evidence must be 10 MB or smaller");String type=file.getContentType()==null?"":file.getContentType().toLowerCase(Locale.ROOT);if(!Set.of("image/jpeg","image/png","image/webp","application/pdf").contains(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only JPEG, PNG, WebP and PDF survey evidence is supported");
 try{byte[] bytes=file.getBytes();if(!valid(bytes,type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Uploaded file signature does not match its content type");String ext=switch(type){case "image/jpeg"->".jpg";case "image/png"->".png";case "image/webp"->".webp";default->".pdf";};String key=storage.put(root,"surveys",p.tenantId(),UUID.randomUUID()+ext,bytes,type);
 try{SiteSurveyAttachment a=new SiteSurveyAttachment();a.setId(UUID.randomUUID());a.setTenantId(p.tenantId());a.setSurveyId(surveyId);a.setOriginalName(safeName(file.getOriginalFilename()));a.setStorageKey(key);a.setContentType(type);a.setSizeBytes(bytes.length);a.setUploadedBy(p.userId());a.setCreatedAt(Instant.now());return attachments.save(a);}catch(RuntimeException ex){try{storage.delete(root,key);}catch(IOException cleanup){ex.addSuppressed(cleanup);}throw ex;}
 }catch(IOException ex){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to store survey evidence",ex);}}
 public List<SiteSurveyAttachment> list(UUID surveyId,Principal p){surveys.get(surveyId,p);return attachments.findByTenantIdAndSurveyIdOrderByCreatedAtAsc(p.tenantId(),surveyId);}
 public Download download(UUID surveyId,UUID attachmentId,Principal p){surveys.get(surveyId,p);SiteSurveyAttachment a=attachments.findByIdAndTenantIdAndSurveyId(attachmentId,p.tenantId(),surveyId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Survey attachment not found"));try{return new Download(a,storage.get(root,a.getStorageKey()));}catch(IOException ex){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to read survey evidence",ex);}}
 private boolean valid(byte[] b,String type){if(type.equals("application/pdf"))return b.length>=5&&b[0]=='%'&&b[1]=='P'&&b[2]=='D'&&b[3]=='F'&&b[4]=='-';if(type.equals("image/jpeg"))return b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255;if(type.equals("image/png"))return b.length>=8&&(b[0]&255)==137&&b[1]=='P'&&b[2]=='N'&&b[3]=='G';return b.length>=12&&b[0]=='R'&&b[1]=='I'&&b[2]=='F'&&b[3]=='F'&&b[8]=='W'&&b[9]=='E'&&b[10]=='B'&&b[11]=='P';}
 private String safeName(String value){if(value==null||value.isBlank())return "survey-evidence";String normalized=value.replace("\\","/");String name=normalized.substring(normalized.lastIndexOf('/')+1).replaceAll("[^A-Za-z0-9._-]","_");return name.length()>200?name.substring(name.length()-200):name;}
 public record Download(SiteSurveyAttachment attachment,byte[] content){}
}
